// Analyze engagement metrics
const allPosts = $input.item.json;
const metrics = {
  total_posts: allPosts.length,
  platforms: ['facebook', 'instagram', 'linkedin', 'twitter'],
  total_likes: 0,
  total_comments: 0,
  total_shares: 0,
  total_impressions: 0,
  top_performing: [],
  low_performing: [],
  analyzed_at: new Date().toISOString()
};

allPosts.forEach(post => {
  const likes = post.likes || post.reactions?.summary?.total_count || 0;
  const comments = post.comments?.summary?.total_count || post.comment_count || 0;
  const shares = post.shares || 0;
  const impressions = post.impressions || 0;

  metrics.total_likes += likes;
  metrics.total_comments += comments;
  metrics.total_shares += shares;
  metrics.total_impressions += impressions;

  const engagementRate = (likes + comments + shares) / (impressions || 1) * 100;

  if (engagementRate > 5) {
    metrics.top_performing.push({
      post_id: post.id,
      platform: post.platform || 'unknown',
      engagement_rate: engagementRate,
      likes: likes,
      comments: comments,
      shares: shares
    });
  } else if (engagementRate < 1) {
    metrics.low_performing.push({
      post_id: post.id,
      platform: post.platform || 'unknown',
      engagement_rate: engagementRate,
      likes: likes,
      comments: comments,
      shares: shares
    });
  }
});

return metrics;

